  from (select '<aside class="questao" data-id="1cde05ce-6132-547a-825d-de375565994c" data-gabarito="27"><p>(PAS-UEM 2023, 1ª etapa) Sobre solos, assinale o que for correto.</p><p>(01) Possuem profundidade influenciada pela inclinação do relevo.</p><p>(02) Solos de climas temperados são mais rasos que solos de clima tropical.</p><p>(04) A cobertura do solo com restos vegetais de cultivos anteriores diminui a taxa de infiltração e a umidade no solo.</p><p>(08) Pedogênese corresponde ao processo que dá origem ao solo.</p><p>(16) A fertilidade mineral do solo é influenciada pela rocha matriz.</p><p>Dê a soma dos itens corretos.</p></aside>'::text as bloco) q
 where r.slug = 'horizontes-e-perfis-de-solo' and strpos(r.corpo, '1cde05ce-6132-547a-825d-de375565994c') = 0;

