                   from strpos(r.corpo, '<h2>Para revisar</h2>') for 21)
    else r.corpo || q.bloco
  end
  from (select '<aside class="questao" data-id="b736aba7-1593-5272-8379-31da273d1b2d" data-gabarito="29"><p>(PAS-UEM 2023, 1ª etapa) Sobre estruturas e processos de constituição das paisagens, assinale o que for correto.</p><p>(01) Serrapilheira é a denominação para a matéria orgânica depositada sobre a superfície dos solos de áreas de floresta.</p><p>(02) Regiões áridas possuem, como resultado da disponibilidade hídrica, solos com maior acidez e com deficiência de sais minerais.</p><p>(04) As queimadas no Cerrado podem ocorrer de modo natural, e as cinzas resultantes podem contribuir como fonte de minerais para solos e plantas.</p><p>(08) Solos muito arenosos apresentam menor teor de matéria orgânica quando comparados a solos argilosos.</p><p>(16) A sedimentação é um processo predominante nas planícies.</p><p>Dê a soma dos itens corretos.</p></aside>'::text as bloco) q
