-- colonizacao-na-america: PAS-UEM 2024|Etapa 2|4
update resumos r set corpo = case
    when strpos(r.corpo, '<h2>Para revisar</h2>') > 0
      then overlay(r.corpo placing q.bloco || '<h2>Para revisar</h2>'
                   from strpos(r.corpo, '<h2>Para revisar</h2>') for 21)
    else r.corpo || q.bloco
  end
  from (select '<aside class="questao" data-id="7a1fd01b-18e0-5bc5-aeb1-b36c5d965029" data-gabarito="15"><p>(PAS-UEM 2024, 2ª etapa) A partir do século XV, os europeus deixaram as fronteiras do seu continente e se expandiram pelo mundo, alcançando outras regiões, como a América, objeto de conquista e de exploração. A respeito do impacto das invasões conquistadoras europeias sobre as sociedades indígenas presentes no continente americano, assinale o que for correto.</p><p>(01) A conquista do Império Inca, com sua capital localizada na cidade de Cuzco, ocorreu na primeira metade do século XVI e foi liderada por Francisco Pizarro, que conseguiu invadir a capital e desestabilizar o Império.</p><p>(02) Os europeus oprimiram a cultura das sociedades indígenas impondo sua própria cultura (religião, idioma, práticas políticas e sociais).</p><p>(04) Quando os europeus chegaram ao continente americano, os maias, que ocupavam as regiões da Península de Iucatã, no México, e os territórios hoje pertencentes à Guatemala, a Belize, a Honduras e a El Salvador, encontravam-se mergulhados em um processo de desarticulação social.</p><p>(08) As doenças trazidas pelos europeus (sarampo, varíola, gripe) dizimaram grande parte da população indígena, pois esta não possuía defesas biológicas para enfrentar essas enfermidades.</p><p>(16) Do contato entre europeus e astecas (presentes no extremo sul do continente) houve a criação de alianças militares e econômicas que fortaleceram essa sociedade indígena.</p><p>Dê a soma dos itens corretos.</p></aside>'::text as bloco) q
 where r.slug = 'colonizacao-na-america' and strpos(r.corpo, '7a1fd01b-18e0-5bc5-aeb1-b36c5d965029') = 0;

-- praticas-de-conservacao: PAS-UEM 2024|Etapa 2|12
update resumos r set corpo = case
    when strpos(r.corpo, '<h2>Para revisar</h2>') > 0
      then overlay(r.corpo placing q.bloco || '<h2>Para revisar</h2>'
                   from strpos(r.corpo, '<h2>Para revisar</h2>') for 21)
    else r.corpo || q.bloco
  end
  from (select '<aside class="questao" data-id="041bd10f-e7ab-5c7e-8153-4eec28b1800b" data-gabarito="25"><p>(PAS-UEM 2024, 2ª etapa) Assinale o que for correto.</p><p>(01) A retenção de água no solo é influenciada por sua granulometria, o que, consequentemente, interfere no desenvolvimento das plantas.</p><p>(02) Solos da Caatinga são mais propensos ao processo de lixiviação do que solos da Amazônia.</p><p>(04) Soja e arroz são exemplos de lavouras permanentes, enquanto o café e o cacau são exemplos de lavouras temporárias.</p><p>(08) Parâmetros climatológicos como precipitação e temperatura são determinantes para o zoneamento agrícola.</p><p>(16) Calagem é a denominação da técnica agrícola para aumentar o pH do solo com o uso de calcário.</p><p>Dê a soma dos itens corretos.</p></aside>'::text as bloco) q
 where r.slug = 'praticas-de-conservacao' and strpos(r.corpo, '041bd10f-e7ab-5c7e-8153-4eec28b1800b') = 0;

