    else r.corpo || q.bloco
  end
  from (select '<aside class="questao" data-id="84a7db0b-3a6e-5f07-b06a-c2cad21dd264" data-gabarito="23"><p>(PAS-UEM 2025, 2ª etapa) Sobre os componentes da cultura, entendida como um sistema, assinale o que for correto.</p><p>(01) O traço cultural é a menor unidade de uma cultura e pode ser material ou imaterial.</p><p>(02) A combinação de traços culturais em uma atividade específica forma um complexo cultural.</p><p>(04) Área cultural é uma porção do espaço geográfico onde predominam determinados complexos culturais.</p><p>(08) Uma protocultura é formada por complexos culturais ainda não sancionados pela autoridade legal de uma área cultural.</p><p>(16) Traços culturais semelhantes podem ter significados distintos em diferentes complexos culturais.</p><p>Dê a soma dos itens corretos.</p></aside>'::text as bloco) q
 where r.slug = 'cultura' and strpos(r.corpo, '84a7db0b-3a6e-5f07-b06a-c2cad21dd264') = 0;

-- neoclassicismo: PAS-UEM 2016|Etapa 2|1
update resumos r set corpo = case
    when strpos(r.corpo, '<h2>Para revisar</h2>') > 0
      then overlay(r.corpo placing q.bloco || '<h2>Para revisar</h2>'
                   from strpos(r.corpo, '<h2>Para revisar</h2>') for 21)
    else r.corpo || q.bloco
  end
  from (select '<aside class="questao" data-id="3fbbb709-0087-541b-a8d4-f18a359b6c2d" data-gabarito="29"><p>(PAS-UEM 2016, 2ª etapa) Segundo Ian Chilvers (Dicionário Oxford de Arte. São Paulo: Martins Fontes, 2001, p. 374), o Neoclassicismo expressou “o desejo de recriar o espírito heróico, bem como os padrões decorativos da arte da Grécia e de Roma”. Ele afirmou também que os artistas neoclássicos, assim como seus contemporâneos, no século XVIII, os filósofos iluministas, possuíam um interesse “mais científico” pela Antiguidade Clássica. Levando em conta essas assertivas, e conhecimentos correlatos, assinale o que estiver correto.</p><p>(01) A arquitetura neoclássica teve como um de seus aspectos mais pronunciados a monumentalidade, além de uma forte preocupação com a simetria.</p><p>(02) A análise histórica dos prédios neoclássicos mostra que sua principal influência estilística vinha das pirâmides egípcias descobertas pelos europeus na Época do Renascimento.</p><p>(04) Inserida em sua época histórica, a arquitetura neoclássica mostra-se uma reação sóbria e crítica à frivolidade e aos exageros ornamentais que seus adeptos viam no chamado estilo rococó.</p><p>(08) Encontram-se expressões da arquitetura neoclássica em muitas edificações governamentais construídas na primeira metade do século XX na Itália, na Alemanha e no Brasil.</p><p>(16) A regularidade das proporções e o cuidado em evitar cores berrantes foram características importantes da arquitetura neoclássica praticada em grandes edificações públicas.</p><p>Dê a soma dos itens corretos.</p></aside>'::text as bloco) q
 where r.slug = 'neoclassicismo' and strpos(r.corpo, '3fbbb709-0087-541b-a8d4-f18a359b6c2d') = 0;
